// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 blockNumber, uint256 warpTime, uint256 callerBalance) public {
        blockNumber = bound(blockNumber, 1, type(uint256).max - 1);
        vm.roll(blockNumber);
        warpTime = bound(warpTime, 1, type(uint256).max - 1);
        vm.warp(warpTime);
        callerBalance = bound(callerBalance, 10 ether, type(uint256).max - 1);
        address caller = makeAddr("caller");
        vm.deal(caller, callerBalance);
        if (blockNumber % 15 != 0) {
            blockNumber = blockNumber - (blockNumber % 15);
            vm.roll(blockNumber);
        }
        uint256 callerBefore = caller.balance;
        uint256 contractBefore = address(c).balance;
        vm.prank(caller);
        (bool ok, ) = address(c).call{value: 10 ether}("");
        require(ok, "fallback reverted");
        assertTrue(caller.balance == callerBefore + contractBefore);
    }
}
